-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 10 recettes, 7 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"donair-halifax","country":"CA","original":"Halifax donair","title":"Donair d’Halifax (pain pita, bœuf épicé et sauce sucrée à l’ail)","en":"Halifax donair","es":"Donair de Halifax","desc":"Pain de bœuf haché épicé rôti en broche, tranché finement dans un pita avec tomates, oignons et une sauce sucrée au lait concentré et à l’ail; mets officiel d’Halifax.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":90,"serv":6,"place":{"slug":"ca-halifax","name":"Halifax","type":"city","lat":44.6488,"lng":-63.5752,"summary":"Capitale de la Nouvelle-Écosse, dont le donair est le mets officiel."},"ing":[["Bœuf haché maigre",1,"kg",null],["Chapelure",30,"g",null],["Origan séché",1,"c. à thé",null],["Paprika",2,"c. à thé",null],["Poivre de Cayenne",0.5,"c. à thé",null],["Ail en poudre",1,"c. à thé",null],["Sel",1.5,"c. à thé",null],["Lait concentré sucré",300,"ml",null],["Vinaigre blanc",80,"ml",null],["Pitas",6,null,null],["Tomates et oignons",1,"portion","en dés"]],"steps":["Pétrir longuement le bœuf avec chapelure, épices et sel jusqu’à texture collante.","Façonner en pain serré et rôtir 1 heure 15 à 180 °C.","Laisser refroidir puis trancher très finement.","Saisir les tranches dans une poêle chaude.","Pour la sauce, fouetter le lait concentré avec l’ail et ajouter le vinaigre en filet jusqu’à épaississement.","Garnir les pitas chauds de viande, tomates, oignons et sauce."],"photo":{"file":"File:Donair (47003391564).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/7a/Donair_%2847003391564%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Donair_(47003391564).jpg","author":"Paulo O from Halifax, Canada","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"poutine-a-trou-acadienne","country":"CA","place":{"slug":"ca-peninsule-acadienne","name":"Péninsule acadienne","type":"region","lat":47.6,"lng":-65,"summary":"Nord-est du Nouveau-Brunswick, cœur de l’Acadie : Caraquet, Shippagan et le Village historique acadien."},"original":"Poutine à trou","title":"Poutine à trou acadienne (chausson aux pommes et canneberges, sirop à la cassonade)","en":"Acadian poutine à trou (apple and cranberry pastry ball in brown sugar syrup)","es":"Poutine à trou acadiana (bola de masa con manzana y arándanos rojos, almíbar de azúcar morena)","desc":"Dessert de la Péninsule acadienne : une boule de pâte farcie de pommes, de raisins secs et de canneberges, percée d’un trou sur le dessus, cuite au four puis arrosée d’un sirop de cassonade versé par le trou.","cat":"Dessert","diff":"medium","prep":40,"cook":35,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Poutine_à_trou","ing":[["Farine tout usage",375,"g",null],["Poudre à pâte",1,"c. à soupe",null],["Sel",0.5,"c. à thé",null],["Graisse végétale ou beurre froid",115,"g","en dés"],["Lait",175,"ml",null],["Pommes",3,null,"pelées, en petits dés"],["Canneberges",75,"g","fraîches ou séchées"],["Raisins secs",50,"g",null],["Sucre",2,"c. à soupe","pour la garniture"],["Cannelle",0.5,"c. à thé",null],["Cassonade",200,"g","pour le sirop"],["Eau",250,"ml","pour le sirop"]],"steps":["Préchauffer le four à 190 °C. Mélanger farine, poudre à pâte et sel, puis sabler avec la graisse jusqu’à obtenir une texture grumeleuse.","Ajouter le lait et mélanger juste assez pour former une pâte souple; la diviser en 6 portions.","Mélanger pommes, canneberges, raisins secs, sucre et cannelle.","Abaisser chaque portion en cercle de 15 cm, déposer la garniture au centre et remonter la pâte en boule en laissant un petit trou sur le dessus.","Cuire 30 à 35 minutes sur une plaque, jusqu’à ce que les boules soient dorées.","Pendant ce temps, faire bouillir la cassonade et l’eau 5 minutes pour obtenir un sirop.","Servir chaud en versant le sirop dans le trou de chaque poutine et autour."],"photo":{"file":"File:Poutine à trous Village historique acadien.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Poutine_%C3%A0_trous_Village_historique_acadien.jpg","page":"https://commons.wikimedia.org/wiki/File:Poutine_%C3%A0_trous_Village_historique_acadien.jpg","author":"Dr Wilson","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"tchaude-cheticamp","country":"CA","place":{"slug":"ca-cheticamp","name":"Chéticamp","type":"locality","lat":46.637,"lng":-60.949,"summary":"Village acadien de l’île du Cap-Breton (Nouvelle-Écosse), sur la côte du golfe du Saint-Laurent."},"original":"Tchaude","title":"Tchaude de Chéticamp (chaudrée acadienne d’aiglefin et de pommes de terre)","en":"Chéticamp tchaude (Acadian haddock and potato chowder)","es":"Tchaude de Chéticamp (sopa acadiana de eglefino y patatas)","desc":"Chaudrée des Acadiens du Cap-Breton : pommes de terre en dés et morceaux d’aiglefin cuits dans un bouillon au lard salé et à l’oignon, adouci au lait et au beurre.","cat":"Soupe","diff":"easy","prep":20,"cook":30,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Chéticamp","ing":[["Filets d’aiglefin",700,"g","en gros morceaux"],["Pommes de terre",1,"kg","en dés"],["Lard salé",100,"g","en petits dés"],["Oignon",1,null,"haché"],["Eau",1,"l",null],["Lait",500,"ml",null],["Beurre",30,"g",null],["Sarriette séchée",1,"c. à thé",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire fondre le lard salé dans une grande casserole, ajouter l’oignon et le faire tomber sans le colorer.","Ajouter les pommes de terre, l’eau et la sarriette; cuire 15 minutes à frémissement.","Déposer l’aiglefin sur les pommes de terre et cuire 8 à 10 minutes, jusqu’à ce que le poisson se défasse.","Verser le lait, ajouter le beurre et réchauffer sans faire bouillir.","Saler, poivrer et servir avec du pain et des biscuits soda."],"photo":{"file":"File:Tchaude de Chéticamp.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/83/Tchaude_de_Ch%C3%A9ticamp.jpg","page":"https://commons.wikimedia.org/wiki/File:Tchaude_de_Ch%C3%A9ticamp.jpg","author":"Paul Joseph from vancouver, bc, canada","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"fricot-acadien","country":"CA","original":"Fricot","title":"Fricot acadien au poulet (ragoût aux pommes de terre et aux grands-pères)","en":"Acadian chicken fricot (chicken, potato and dumpling stew)","es":"Fricot acadiano de pollo (guiso de pollo, patatas y bolas de masa)","desc":"Le plat réconfortant des Acadiens des Maritimes : poulet mijoté avec pommes de terre, oignon et sarriette, auquel on ajoute en fin de cuisson des grands-pères (boulettes de pâte) cuits à la vapeur sur le bouillon.","cat":"Plat principal","diff":"easy","prep":25,"cook":75,"serv":6,"reference":"https://en.wikipedia.org/wiki/Fricot","ing":[["Poulet en morceaux",1.5,"kg",null],["Oignon",1,null,"haché"],["Pommes de terre",6,null,"en cubes"],["Carottes",2,null,"en rondelles"],["Sarriette séchée",1,"c. à soupe",null],["Eau",2,"l",null],["Beurre",30,"g",null],["Sel et poivre",1,"c. à thé",null],["Farine (grands-pères)",250,"g",null],["Poudre à pâte (grands-pères)",1,"c. à soupe",null],["Lait (grands-pères)",175,"ml",null]],"steps":["Dorer le poulet dans le beurre, ajouter l’oignon, puis couvrir d’eau; saler, poivrer et laisser mijoter 45 minutes.","Ajouter pommes de terre, carottes et sarriette, et cuire encore 15 minutes.","Grands-pères : mélanger farine, poudre à pâte et une pincée de sel, puis ajouter le lait pour obtenir une pâte collante.","Déposer la pâte à la cuillère sur le fricot frémissant, couvrir et cuire 15 minutes sans soulever le couvercle.","Servir bien chaud dans des bols."],"photo":{"file":"File:Fricot.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/63/Fricot.jpg","page":"https://commons.wikimedia.org/wiki/File:Fricot.jpg","author":"Thomas Ash","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"garlic-fingers-nouvelle-ecosse","country":"CA","place":{"slug":"ca-nouvelle-ecosse","name":"Nouvelle-Écosse","type":"region","lat":45,"lng":-63,"summary":"Province maritime du Canada : donair, garlic fingers, homard et pétoncles de Digby."},"original":"Garlic fingers","title":"Garlic fingers des Maritimes (pain pizza à l’ail et au fromage)","en":"Maritime garlic fingers","es":"Garlic fingers de las Marítimas (pan de pizza con ajo y queso)","desc":"Spécialité des pizzerias de la Nouvelle-Écosse : une pâte à pizza badigeonnée de beurre à l’ail, couverte de mozzarella, puis coupée en bâtonnets et servie avec une sauce donair ou à l’ail.","cat":"Street food","diff":"easy","prep":15,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Garlic_fingers","ing":[["Pâte à pizza",500,"g",null],["Beurre",60,"g","fondu"],["Ail",4,"gousses","râpées"],["Persil haché",1,"c. à soupe",null],["Mozzarella râpée",250,"g",null],["Sel",1,"pincée",null],["Sauce donair ou sauce à l’ail",125,"ml","pour tremper"]],"steps":["Préchauffer le four à 230 °C et abaisser la pâte sur une plaque ou une pierre à pizza.","Mélanger le beurre fondu, l’ail, le persil et le sel, puis en badigeonner toute la pâte.","Couvrir généreusement de mozzarella.","Cuire 12 à 15 minutes, jusqu’à ce que le fromage soit doré et bouillonnant.","Couper en longs bâtonnets plutôt qu’en pointes et servir avec la sauce pour tremper."],"photo":{"file":"File:Garlic Fingers.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/a5/Garlic_Fingers.jpg","page":"https://commons.wikimedia.org/wiki/File:Garlic_Fingers.jpg","author":"Simon Laroche","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"persian-roll-thunder-bay","country":"CA","place":{"slug":"ca-thunder-bay","name":"Thunder Bay","type":"city","lat":48.3809,"lng":-89.2477,"summary":"Ville du nord-ouest de l’Ontario, au bord du lac Supérieur, patrie du Persian roll."},"original":"Persian","title":"Persian de Thunder Bay (roulé à la cannelle glacé aux petits fruits roses)","en":"Thunder Bay Persian (cinnamon bun with pink berry icing)","es":"Persian de Thunder Bay (rollo de canela con glaseado rosa de bayas)","desc":"Pâtisserie emblématique de Thunder Bay depuis les années 1940 : une brioche frite en spirale à la cannelle, aplatie, puis nappée d’un glaçage rose aux petits fruits (fraises ou framboises).","cat":"Dessert","diff":"medium","prep":30,"cook":15,"serv":8,"reference":"https://en.wikipedia.org/wiki/Persian_(food)","ing":[["Farine tout usage",450,"g",null],["Levure sèche active",1,"sachet","8 g"],["Lait tiède",250,"ml",null],["Sucre",60,"g",null],["Beurre",60,"g","fondu"],["Œuf",1,null,null],["Sel",0.5,"c. à thé",null],["Cannelle moulue",2,"c. à thé",null],["Cassonade",60,"g","pour la garniture"],["Huile de friture",1,"l",null],["Sucre à glacer",250,"g","pour le glaçage"],["Framboises ou fraises écrasées",60,"g","pour le glaçage"],["Beurre ramolli",30,"g","pour le glaçage"]],"steps":["Délayer la levure dans le lait tiède avec une pincée de sucre; ajouter le sucre, le beurre fondu, l’œuf, le sel et la farine, puis pétrir 8 minutes.","Laisser lever 1 heure, abaisser en rectangle, saupoudrer de cassonade et de cannelle, rouler serré et couper en 8 tranches.","Aplatir chaque tranche en disque épais et laisser lever 30 minutes.","Frire dans l’huile à 175 °C environ 2 minutes par côté, puis égoutter sur du papier absorbant.","Glaçage : battre le sucre à glacer avec le beurre et les fruits écrasés jusqu’à obtenir une crème rose épaisse.","Napper généreusement le dessus des Persians refroidis."],"photo":{"file":"File:Persian roll.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/aa/Persian_roll.jpg","page":"https://commons.wikimedia.org/wiki/File:Persian_roll.jpg","author":"Bayonett","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"pizza-hawaienne-chatham","country":"CA","place":{"slug":"ca-chatham-ontario","name":"Chatham (Ontario)","type":"city","lat":42.4048,"lng":-82.191,"summary":"Ville du sud-ouest de l’Ontario où le restaurant Satellite a créé la pizza hawaïenne en 1962."},"original":"Pizza hawaïenne","title":"Pizza hawaïenne de Chatham (jambon et ananas)","en":"Chatham Hawaiian pizza (ham and pineapple)","es":"Pizza hawaiana de Chatham (jamón y piña)","desc":"Pizza créée en 1962 par Sam Panopoulos au restaurant Satellite de Chatham, en Ontario : sauce tomate, mozzarella, jambon et ananas en conserve pour le contraste sucré-salé.","cat":"Plat principal","diff":"easy","prep":20,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Hawaiian_pizza","ing":[["Pâte à pizza",500,"g",null],["Sauce tomate à pizza",150,"ml",null],["Mozzarella râpée",250,"g",null],["Jambon cuit",150,"g","en dés ou en lanières"],["Ananas en morceaux",200,"g","bien égouttés"],["Origan séché",1,"c. à thé",null]],"steps":["Préchauffer le four à 240 °C avec la plaque ou la pierre à l’intérieur.","Abaisser la pâte et l’étaler de sauce tomate en laissant un rebord.","Parsemer de mozzarella, puis répartir le jambon et les morceaux d’ananas bien égouttés.","Saupoudrer d’origan.","Cuire 12 à 15 minutes jusqu’à ce que la croûte soit dorée et le fromage gratiné, puis couper en pointes."],"photo":{"file":"File:Hawaiian Pizza - Satellite Restaurant - Chatham, ON.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/c/c5/Hawaiian_Pizza_-_Satellite_Restaurant_-_Chatham%2C_ON.jpg","page":"https://commons.wikimedia.org/wiki/File:Hawaiian_Pizza_-_Satellite_Restaurant_-_Chatham,_ON.jpg","author":"JFVoll","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"queues-de-castor-ottawa","country":"CA","place":{"slug":"ca-ottawa","name":"Ottawa","type":"city","lat":45.4215,"lng":-75.6972,"summary":"Capitale du Canada; ses queues de castor se dégustent au marché By et sur le canal Rideau."},"original":"Queue de castor","title":"Queues de castor (pâte frite étirée, cannelle et sucre)","en":"Beaver tails (stretched fried dough with cinnamon sugar)","es":"Colas de castor (masa frita estirada con canela y azúcar)","desc":"Pâte levée de blé entier étirée à la main en forme de queue de castor, frite puis roulée dans le sucre à la cannelle : la collation des patinoires et du marché By d’Ottawa.","cat":"Street food","diff":"medium","prep":30,"cook":15,"serv":8,"reference":"https://en.wikipedia.org/wiki/BeaverTails","ing":[["Farine de blé entier",200,"g",null],["Farine tout usage",250,"g",null],["Levure sèche active",1,"sachet","8 g"],["Lait tiède",250,"ml",null],["Sucre",50,"g",null],["Œuf",1,null,null],["Beurre fondu",45,"g",null],["Sel",1,"c. à thé",null],["Huile de friture",1,"l",null],["Sucre (enrobage)",100,"g",null],["Cannelle moulue (enrobage)",2,"c. à thé",null],["Citron",1,null,"facultatif, pour servir"]],"steps":["Délayer la levure dans le lait tiède avec le sucre; ajouter l’œuf, le beurre, le sel et les deux farines, puis pétrir 6 à 8 minutes.","Laisser lever 1 heure, puis diviser en 8 boules.","Étirer chaque boule à la main en ovale plat de 20 cm, en forme de queue de castor.","Frire dans l’huile à 175 °C environ 1 minute par côté, jusqu’à ce que la pâte gonfle et dore.","Égoutter rapidement et rouler aussitôt dans le mélange de sucre et de cannelle.","Servir chaud, avec un trait de jus de citron si désiré."],"photo":{"file":"File:Cinnamon and sugar BeaverTail.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/8f/Cinnamon_and_sugar_BeaverTail.jpg","page":"https://commons.wikimedia.org/wiki/File:Cinnamon_and_sugar_BeaverTail.jpg","author":"Jon Kolbert","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"langues-de-morue-terre-neuve","country":"CA","place":"ca-terre-neuve","original":"Cod tongues","title":"Langues et joues de morue de Terre-Neuve (frites au lard salé)","en":"Newfoundland cod tongues and cheeks","es":"Lenguas y carrilleras de bacalao de Terranova","desc":"Mets traditionnel des ports de Terre-Neuve : les langues et joues de morue, farinées puis frites à la poêle dans le gras de lard salé et servies avec les grillades (scrunchions).","cat":"Poisson","diff":"easy","prep":15,"cook":15,"serv":4,"reference":"https://en.wikipedia.org/wiki/Cod_tongue","ing":[["Langues et joues de morue",700,"g","rincées et épongées"],["Lard salé",120,"g","en petits dés"],["Farine",100,"g",null],["Sel",1,"c. à thé",null],["Poivre",0.5,"c. à thé",null],["Citron",1,null,"en quartiers"]],"steps":["Faire revenir le lard salé à feu moyen jusqu’à ce que les dés soient croustillants; réserver ces grillades et garder le gras dans la poêle.","Mélanger la farine, le sel et le poivre dans un sac ou une assiette.","Enrober les langues et joues de morue de farine en secouant l’excédent.","Les frire dans le gras chaud 3 à 4 minutes par côté, jusqu’à ce qu’elles soient dorées et croustillantes.","Servir parsemé des grillades de lard, avec des quartiers de citron."],"photo":{"file":"File:Cod tongues and cheeks for dinner (14081659530).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/32/Cod_tongues_and_cheeks_for_dinner_%2814081659530%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Cod_tongues_and_cheeks_for_dinner_(14081659530).jpg","author":"Jeremy T. Hetzel from Boston, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"flipper-pie-terre-neuve","country":"CA","place":"ca-terre-neuve","original":"Flipper pie","title":"Flipper pie de Terre-Neuve (pâté aux nageoires de phoque)","en":"Newfoundland flipper pie (seal flipper pie)","es":"Flipper pie de Terranova (pastel de aletas de foca)","desc":"Pâté traditionnel du printemps à Terre-Neuve, à l’époque de la chasse au phoque : nageoires de phoque du Groenland braisées avec lard salé, oignon et légumes racines, sous une croûte de pâte.","cat":"Plat principal","diff":"hard","prep":45,"cook":180,"serv":6,"reference":"https://en.wikipedia.org/wiki/Flipper_pie","ing":[["Nageoires de phoque",4,null,"dégraissées"],["Vinaigre",60,"ml","pour le trempage"],["Lard salé",120,"g","en dés"],["Oignons",2,null,"hachés"],["Carottes",2,null,"en dés"],["Navet (rutabaga)",1,null,"en dés"],["Pommes de terre",3,null,"en dés"],["Farine",3,"c. à soupe",null],["Bouillon de bœuf",750,"ml",null],["Sauce Worcestershire",1,"c. à soupe",null],["Sarriette",1,"c. à thé",null],["Pâte brisée",400,"g","pour le couvercle"]],"steps":["Retirer tout le gras blanc des nageoires, puis les faire tremper 1 heure dans de l’eau froide additionnée de vinaigre; rincer et couper en morceaux.","Faire fondre le lard salé, fariner les morceaux de nageoire et les dorer dans le gras avec les oignons.","Ajouter le bouillon, la Worcestershire et la sarriette; couvrir et cuire 2 heures au four à 175 °C.","Ajouter carottes, navet et pommes de terre et poursuivre 30 minutes.","Transférer dans un plat, couvrir d’une abaisse de pâte entaillée et cuire 30 minutes à 200 °C jusqu’à ce que la croûte soit dorée."],"photo":{"file":"File:Seal Flipper Pie - Woodstock Colonial Restaurant (6061055845) (cropped).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/51/Seal_Flipper_Pie_-_Woodstock_Colonial_Restaurant_%286061055845%29_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Seal_Flipper_Pie_-_Woodstock_Colonial_Restaurant_(6061055845)_(cropped).jpg","author":"Haydn Blackey from Cardiff, Wales","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0"}}]$batch$::jsonb);
